head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.cnt_day = 0;
scwin.cnt_time = 0;
scwin.cnt_month = 0;

// 화면 리사이징
//

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.libRoundPanel.PanelToGroupBox(panel_1);
        fn_CtrlBtn("no_data");
        ins_combo_set(dts_LIST_STAT_CD, "ULDINS31000.xml", SCREN_PROCS_TP_CD_01, "00714", "ALL"); // 00714 -LIST_STAT_CD

        $c.stf.setFromToDate(5, edt_pSTD_CD_GRNT_DD_SDATE, edt_pSTD_CD_GRNT_DD_EDATE);
        edt_pSTD_CD_GRNT_DD_DATE.setValue($c.ut.cGetToday("yyyymmdd"));
        edt_pSEARCH_YYYY.setValue($c.ut.cGetToday("yyyymmdd").substring(0, 4));

        /*
        날짜검색 부분 디자인이 겹쳐 있어서 작업시 위에꺼 내리고 작업해야 함.
         */
        label_27.hide();
        edt_pSTD_CD_GRNT_DD_DATE.hide();
        img_pSTD_CD_GRNT_DD_DATE.hide();
        cmb_pLIST_STAT_CD.hide();
        label_9.hide();
        edt_pSEARCH_YYYY.hide();
        label_12.hide();
        cmb_pACTIV_TP_CD.hide();

        // 활성구분 콤보설정
        cmb_pACTIV_TP_CD.setValue("");

        // 검색년도 OnKeyUp
        await scwin.edt_pSEARCH_YYYY_onkeyup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS31000.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name edt_pSEARCH_YYYY_onkeyup
 * @description 검색년도 입력시 해당년도의 월말일을 가져온다
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.edt_pSEARCH_YYYY_onkeyup = async function() {
    try {
        if (edt_pSEARCH_YYYY.getValue().length === 4) {
            // 데이터셋 초기화
            dts_MM_END_DATE.removeAll();
            const sbmOptions = {
                id : "sbm_dts_MM_END_DATE",
                action : "/listingCommon.do",
                ref : "",
                target : "dts_MM_END_DATE=body.content",
                isProcessMsg : false
            };

            const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
            // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS31000.edt_pSEARCH_YYYY_onkeyup" });
    }
};

/**
 * @method
 * @name btn_search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_search_onclick = async function() {
    try {
        if (tab_IsurInfo.getSelectedTabIndex() === "1") {
            await scwin.ins_search_day();
        } else if (tab_IsurInfo.getSelectedTabIndex() === "2") {
            await scwin.ins_search_time();
        } else if (tab_IsurInfo.getSelectedTabIndex() === "3") {
            await scwin.ins_search_month();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS31000.btn_search_onclick" });
    }
};

/**
 * @method
 * @name dts_StdCdDayList_OnLoadCompleted
 * @description dts_StdCdDayList 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_StdCdDayList_OnLoadCompleted = function(rowcount) {
    try {
        if (rowcount === 0) {
            btn_excelsave.setDisabled(true);
            btn_excelsave.setBackgroundImage("../img/btn_excelsave_d.gif");
        } else {
            btn_excelsave.setDisabled(false);
            btn_excelsave.setBackgroundImage("../img/btn_excelsave.gif");
        }
        scwin.cnt_day = rowcount;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDINS31000.dts_StdCdDayList_OnLoadCompleted" });
    }
};

