/**
 * @method
 * @name tab_IsurInfo_OnSelChanged
 * @description tab Isur Info On Sel Changed 처리
 * @param {*} nIndex nIndex
 * @returns {void}
 * @hidden N
 */
scwin.tab_IsurInfo_OnSelChanged = function(nIndex) {
    try {
        if (nIndex === "2") {
            label_3.show("");
            edt_pSTD_CD_GRNT_DD_DATE.show("");
            label_6.hide();
            edt_pSTD_CD_GRNT_DD_SDATE.hide();
            img_pSTD_CD_GRNT_DD_SDATE.hide();
            edt_pSTD_CD_GRNT_DD_EDATE.hide();
            img_pSTD_CD_GRNT_DD_EDATE.hide();
            label_27.show("");
            edt_pSTD_CD_GRNT_DD_DATE.show("");
            img_pSTD_CD_GRNT_DD_DATE.show("");
            cmb_pLIST_STAT_CD.show("");
            label_9.hide();
            edt_pSEARCH_YYYY.hide();
            label_12.hide();
            cmb_pACTIV_TP_CD.hide();
        } else if (nIndex === "1") {
            label_3.show("");
            edt_pSTD_CD_GRNT_DD_DATE.show("");
            label_6.show("");
            edt_pSTD_CD_GRNT_DD_SDATE.show("");
            img_pSTD_CD_GRNT_DD_SDATE.show("");
            edt_pSTD_CD_GRNT_DD_EDATE.show("");
            img_pSTD_CD_GRNT_DD_EDATE.show("");
            label_27.hide();
            edt_pSTD_CD_GRNT_DD_DATE.hide();
            img_pSTD_CD_GRNT_DD_DATE.hide();
            cmb_pLIST_STAT_CD.hide();
            label_9.hide();
            edt_pSEARCH_YYYY.hide();
            label_12.hide();
            cmb_pACTIV_TP_CD.hide();
        } else if (nIndex === "3") {
            label_3.hide();
            edt_pSTD_CD_GRNT_DD_DATE.hide();
            label_6.hide();
            edt_pSTD_CD_GRNT_DD_SDATE.hide();
            img_pSTD_CD_GRNT_DD_SDATE.hide();
            edt_pSTD_CD_GRNT_DD_EDATE.hide();
            img_pSTD_CD_GRNT_DD_EDATE.hide();
            label_27.hide();
            edt_pSTD_CD_GRNT_DD_DATE.hide();
            img_pSTD_CD_GRNT_DD_DATE.hide();
            cmb_pLIST_STAT_CD.hide();
            label_9.show("");
            edt_pSEARCH_YYYY.show("");
            label_12.show("");
            cmb_pACTIV_TP_CD.show("");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDINS31000.tab_IsurInfo_OnSelChanged" });
    }
};

/**
 * @method
 * @name img_pSTD_CD_GRNT_DD_SDATE_onclick
 * @description img_pSTD_CD_GRNT_DD_SDATE 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_pSTD_CD_GRNT_DD_SDATE_onclick = function() {
    try {
        popUpCalendar2(edt_pSTD_CD_GRNT_DD_SDATE);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDINS31000.img_pSTD_CD_GRNT_DD_SDATE_onclick" });
    }
};

/**
 * @method
 * @name img_pSTD_CD_GRNT_DD_EDATE_onclick
 * @description img_pSTD_CD_GRNT_DD_EDATE 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_pSTD_CD_GRNT_DD_EDATE_onclick = function() {
    try {
        popUpCalendar2(edt_pSTD_CD_GRNT_DD_EDATE);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDINS31000.img_pSTD_CD_GRNT_DD_EDATE_onclick" });
    }
};

/**
 * @method
 * @name btn_excelsave_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_excelsave_onclick = async function() {
    try {
        $c.stf.doLogSave("ULDINS31000.xml", SCREN_PROCS_TP_CD_07);
        if (tab_IsurInfo.getSelectedTabIndex() === "1") {
            if (scwin.cnt_day === 0) {
                await $c.win.alert("다운로드할 자료가 없습니다");
                return;
            }
            scwin.ins_excel_download("day");
        } else if (tab_IsurInfo.getSelectedTabIndex() === "2") {
            if (scwin.cnt_time === 0) {
                await $c.win.alert("다운로드할 자료가 없습니다");
                return;
            }
            scwin.ins_excel_download("time");
        } else if (tab_IsurInfo.getSelectedTabIndex() === "3") {
            if (scwin.cnt_month === 0) {
                await $c.win.alert("다운로드할 자료가 없습니다");
                return;
            }
            scwin.ins_excel_download("month");
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS31000.btn_excelsave_onclick" });
    }
};

/**
 * @method
 * @name img_pSTD_CD_GRNT_DD_DATE_onclick
 * @description img_pSTD_CD_GRNT_DD_DATE 클릭 이벤트
