    }
};

/**
 * @method
 * @name cmb_pLIST_STAT_CD_onselchange
 * @description cmb_pLIST_STAT_CD onselchange 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.cmb_pLIST_STAT_CD_onselchange = async function() {
    try {
        await scwin.ins_search_time();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS31000.cmb_pLIST_STAT_CD_onselchange" });
    }
};

/**
 * @method
 * @name edt_pSEARCH_YYYY_onkeyup
 * @description edt_pSEARCH_YYYY 키 입력 이벤트
 * @param {*} keycode keycode
 * @param {*} skeycode skeycode
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.edt_pSEARCH_YYYY_onkeyup = async function(keycode, skeycode) {
    try {
        await scwin.edt_pSEARCH_YYYY_onkeyup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS31000.edt_pSEARCH_YYYY_onkeyup" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name ins_search_day
 * @description 통계  목록 조회한다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ins_search_day = async function() {
    if (edt_pSTD_CD_GRNT_DD_SDATE.getValue().length !== 8) {
        await $c.win.alert("조회 시작일 날자을 8자리(예:2012-10-10) 입력하십시요");
        return false;
    }
    if (edt_pSTD_CD_GRNT_DD_EDATE.getValue().length !== 8) {
        await $c.win.alert("조회 마지막 날자를 8자리(예:2013-10-10) 입력하십시요");
        return false;
    }

    // 검색일 체크
    if ($c.stf.compareFromToDate2(edt_pSTD_CD_GRNT_DD_SDATE, edt_pSTD_CD_GRNT_DD_EDATE) === false) {
        return false;
    }
    tab_IsurInfo.setSelectedTabIndex("1");

    // 데이터셋 초기화
    dts_StdCdDayList.removeAll();
    dts_IsuInstDayList.removeAll();
    dts_BndDayList.removeAll();

    const sbmOptions = {
        id : "sbm_dts_StdCdDayList",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_StdCdDayList=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    const sbmOptions2 = {
        id : "sbm_dts_IsuInstDayList",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_IsuInstDayList=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
    // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    const sbmOptions3 = {
        id : "sbm_dts_BndDayList",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_BndDayList=body.content",
        isProcessMsg : false
    };

    const sbmRtn3 = await $c.sbm.executeDynamic(sbmOptions3);
    // TODO Stage2: sbmRtn3 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name ins_search_time
 * @description 통계  목록 조회한다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ins_search_time = async function() {
    if (edt_pSTD_CD_GRNT_DD_DATE.getValue().length !== 8) {
        await $c.win.alert("표준코드부여일 날짜를 8자리(예:2013-10-10) 입력하십시요");
        return false;
    }
    tab_IsurInfo.setSelectedTabIndex("2");

    // 데이터셋 초기화
    dts_StdCdTimeList.removeAll();
    dts_BndTimeList.removeAll();

    const sbmOptions = {
        id : "sbm_dts_StdCdTimeList",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_StdCdTimeList=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    const sbmOptions2 = {
        id : "sbm_dts_BndTimeList",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_BndTimeList=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
    // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name ins_search_month
 * @description 월별코드현황 조회한다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ins_search_month = async function() {
    if (edt_pSEARCH_YYYY.getValue().length !== 4) {
        await $c.win.alert("검색년도를 4자리(예:2014) 입력하십시요");
        return false;
    }
    tab_IsurInfo.setSelectedTabIndex("3");

    // 데이터셋 초기화
    dts_StdByddStat.removeAll();

    // 선택 년도의 각월말일을 가져와서 파라메터로 던진다. 1~12월
    for (let i = 1; i < 13; i++) {
        url += "&{P}V_YYYYMMDD" + i + "=" + dts_MM_END_DATE.getCellData(i, "END_DATE"); // 형식:"&{P}V_YYYYMMDD1=20140131"

    }
    const sbmOptions = {
        id : "sbm_dts_StdByddStat",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_StdByddStat=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name ins_excel_download
 * @description ins excel download 처리
 * @param {*} gubun gubun
 * @returns {void}
 * @hidden N
 */
scwin.ins_excel_download = function(gubun) {
    if (gubun === "day") {

        // file_dts_List.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인
        file_dts_List.insertRow(0);
        file_dts_List.insertRow(0);
        file_dts_List.setCellData(1, "4", edt_pSTD_CD_GRNT_DD_SDATE.getValue() + "~" + edt_pSTD_CD_GRNT_DD_EDATE.getValue());
        file_dts_List.insertRow(2);
        file_dts_List.setCellData(3, "1", "a. 전체 종류별");
        let add_num = 4;
        file_dts_List.insertRow(add_num - 1);
        file_dts_List.setCellData(add_num, "1", "구분");
        file_dts_List.setCellData(add_num, "2", "주권");
        file_dts_List.setCellData(add_num, "3", "채권");
        file_dts_List.setCellData(add_num, "4", "선물옵션");
        file_dts_List.setCellData(add_num, "5", "ELS/DLS");
        file_dts_List.setCellData(add_num, "6", "신주인수권");
        file_dts_List.setCellData(add_num, "7", "수익증권");
        file_dts_List.setCellData(add_num, "8", "ELW");
        file_dts_List.setCellData(add_num, "9", "ETN");
        file_dts_List.setCellData(add_num, "10", "투자계약증권");
        file_dts_List.setCellData(add_num, "11", "기타");
        file_dts_List.setCellData(add_num, "12", "합계");
        for (let i = 1; i < 4; i++) {
            file_dts_List.insertRow(i + add_num - 1);
            file_dts_List.setCellData(i + add_num, "1", dts_StdCdDayList.getCellData(i, "LEFT_TITLE"));
            file_dts_List.setCellData(i + add_num, "2", fn_SetComma(dts_StdCdDayList.getCellData(i, "T_STKCERT")));
            file_dts_List.setCellData(i + add_num, "3", fn_SetComma(dts_StdCdDayList.getCellData(i, "T_BND")));
            file_dts_List.setCellData(i + add_num, "4", fn_SetComma(dts_StdCdDayList.getCellData(i, "T_FUTOPT")));
            file_dts_List.setCellData(i + add_num, "5", fn_SetComma(dts_StdCdDayList.getCellData(i, "T_ELS_DLS")));
            file_dts_List.setCellData(i + add_num, "6", fn_SetComma(dts_StdCdDayList.getCellData(i, "T_SUBSRGHT")));
            file_dts_List.setCellData(i + add_num, "7", fn_SetComma(dts_StdCdDayList.getCellData(i, "T_BENFCERT")));
            file_dts_List.setCellData(i + add_num, "8", fn_SetComma(dts_StdCdDayList.getCellData(i, "T_STK_WRNT")));
            file_dts_List.setCellData(i + add_num, "9", fn_SetComma(dts_StdCdDayList.getCellData(i, "T_ETN")));
            file_dts_List.setCellData(i + add_num, "10", fn_SetComma(dts_StdCdDayList.getCellData(i, "T_INVST")));
            file_dts_List.setCellData(i + add_num, "11", fn_SetComma(dts_StdCdDayList.getCellData(i, "T_ETC")));
            file_dts_List.setCellData(i + add_num, "12", fn_SetComma(dts_StdCdDayList.getCellData(i, "T_SUM")));
        }
